{
  "packet_id": "H6-T04-1",
  "claim_id": "C047",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C047.component",
    "value": "Conditions capable of shifting apparent retention should be recorded.",
    "scope": "Applies to roster timing, team size, acquisition mix and changes in onboarding conditions; recording them is not claimed to eliminate their influence.",
    "provenance": {
      "refs": [
        {
          "source_id": "P026",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P026 explicitly supplies the recording recommendation, the named conditions and their potential influence on apparent retention."
    }
  },
  "signal_basis": {
    "component_id": "C047.signal_basis",
    "value": "Observe concentrations of onboarding trajectories by milestone position, waiting duration, returns to active work and time to publication under common observation conditions. The named contextual conditions can shift apparent retention, motivating their recording and comparison of like observation windows.",
    "scope": "Interpretation of observed onboarding retention patterns; no claim that recording conditions controls their effects or identifies causes.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P026",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the observation conditions, trajectory measurements, contextual influences and restriction against identifying causes from retention alone."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C047.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "Not applicable because the judgment is SUPPORTED."
    }
  },
  "rationale": "Recording conditions that can affect the measured retention patterns is warranted as a means of assessing comparability and interpreting those patterns. This limited recommendation does not require demonstrating that each condition actually caused a shift in the observed cohort.",
  "uncertainty": "The contribution of each condition remains unestablished; recording alone does not remove its influence.",
  "anomalies": []
}
